public PlayerSkillInfo(Skill skill) {
        this.skill = skill;
        level = 1;
        respec();
    }

public void loadFromNBT(NBTTagCompound cmp) {
        level = cmp.getInteger(TAG_LEVEL);
        skillPoints = cmp.getInteger(TAG_SKILL_POINTS);

        unlockables.clear();
        NBTTagCompound unlockablesCmp = cmp.getCompoundTag(TAG_UNLOCKABLES);

        for (String s : unlockablesCmp.getKeySet()) {
            Optional.ofNullable(ReskillableRegistries.UNLOCKABLES.getValue(new ResourceLocation(s.replace(".", ":"))))
                    .ifPresent(unlockables::add);
        }
    }

public void saveToNBT(NBTTagCompound cmp) {
        cmp.setInteger(TAG_LEVEL, level);
        cmp.setInteger(TAG_SKILL_POINTS, skillPoints);

        NBTTagCompound unlockablesCmp = new NBTTagCompound();
        for (Unlockable u : unlockables) {
            unlockablesCmp.setBoolean(u.getKey(), true);
        }
        cmp.setTag(TAG_UNLOCKABLES, unlockablesCmp);
    }

public int getLevel() {
        if (level <= 0) {
            level = 1;
        }
        if (level > skill.getCap()) {
            level = skill.getCap();
        }

        return level;
    }

public int getRank() {
        return 8 * level / skill.getCap();
    }

public int getSkillPoints() {
        return skillPoints;
    }

public boolean isCapped() {
        return level >= skill.getCap();
    }

public int getLevelUpCost() {
        return skill.getLevelUpCost(level);
    }

public boolean isUnlocked(Unlockable u) {
        return unlockables.contains(u);
    }

public void addAbilities(Set<Ability> abilities) {
        for (Unlockable u : unlockables) {
            if (u instanceof Ability) {
                abilities.add((Ability) u);
            }
        }
    }

public void levelUp() {
        level++;
        if (level % skill.getSkillPointInterval() == 0) {
            skillPoints++;
        }
    }

public void setLevel(int level) {
        int interval = skill.getSkillPointInterval();
        skillPoints += level / interval - this.level / interval;
        this.level = level;
    }

public void lock(Unlockable u, EntityPlayer p) {
        skillPoints += u.getCost();
        unlockables.remove(u);
        u.onLock(p);
    }

public void unlock(Unlockable u, EntityPlayer p) {
        skillPoints -= u.getCost();
        unlockables.add(u);
        u.onUnlock(p);
    }

public void respec() {
        unlockables.clear();
        skillPoints = level / skill.getSkillPointInterval();
    }

public void forEachEventHandler(Consumer<IAbilityEventHandler> consumer) {
        unlockables.forEach((u) -> {
            if (u.isEnabled() && u instanceof IAbilityEventHandler) {
                consumer.accept((IAbilityEventHandler) u);
            }
        });
    }

public RequirementHolder() {
        this.requirements = Lists.newArrayList();
        this.forcedEmpty = true;
    }

public RequirementHolder(List<Requirement> requirements) {
        this.requirements = requirements;
        this.forcedEmpty = false;
    }

public RequirementHolder(RequirementHolder... others) {
        this.forcedEmpty = false;
        this.requirements = Lists.newArrayList();
        //TODO Eventually look into optimizing this. Potentially by presorting others by requirement count
        for (RequirementHolder other : others) {
            for (Requirement otherRequirement : other.requirements) {
                boolean noMatch = true;
                int toRemove = -1;
                for (int i = 0; i < requirements.size(); i++) {
                    RequirementComparision match = requirements.get(i).matches(otherRequirement);
                    if (match.equals(RequirementComparision.EQUAL_TO) || match.equals(RequirementComparision.GREATER_THAN)) {
                        noMatch = false;
                        break;
                    } else if (match.equals(RequirementComparision.LESS_THAN)) {
                        toRemove = i;
                        break;
                    }
                }
                if (toRemove >= 0) {
                    requirements.remove(toRemove);
                }
                if (noMatch) {
                    requirements.add(otherRequirement);
                }
            }
        }
    }

public static RequirementHolder realEmpty() {
        return new RequirementHolder();
    }

public static RequirementHolder fromStringList(String[] requirementStringList) {
        List<Requirement> requirements = new ArrayList<>();
        for (String s : requirementStringList) {
            Requirement requirement = ReskillableAPI.getInstance().getRequirementRegistry().getRequirement(s);
            if (requirement != null) {
                requirements.add(requirement);
            }
        }
        return requirements.isEmpty() ? RequirementHolder.realEmpty() : new RequirementHolder(requirements);
    }

public static RequirementHolder fromString(String s) {
        RequirementHolder requirementHolder;
        if (s.matches("(?i)^(none|null|nil)$")) {
            requirementHolder = RequirementHolder.realEmpty();
        } else {
            requirementHolder = fromStringList(s.split(","));
        }

        return requirementHolder;
    }

